// Per-matrix G-way barrier via a MONOTONIC generation counter (no reset, no
// sense reuse -> immune to the reset/reuse races of a sense-reversal barrier).
// bcnt[bid] counts total arrivals ever; after the n-th barrier it equals G*n.
// The arriver that makes bcnt reach G*expected_gen is the last of generation
// expected_gen and bumps gen[bid]:=expected_gen (the release). Waiters spin
// until gen[bid] >= expected_gen. Both bcnt and gen are zeroed each launch.
int expected_gen = 0;
#define MCTA_BARRIER() do {                                            \
    __syncthreads();                                                   \
    if (tid == 0) {                                                    \
        expected_gen += 1;                                             \
        __threadfence();  /* publish this CTA's scratch writes before arrival */ \
        int arrived = atomicAdd(bcnt, 1) + 1;                          \
        if (arrived == G * expected_gen) {                            \
            __threadfence();                                          \
            atomicExch(bsen, expected_gen);  /* release after the fence */ \
        } else {                                                       \
            while (atomicAdd(bsen, 0) < expected_gen) { }  /* coherent spin */ \
        }                                                              \
        __threadfence();  /* order the published scratch before tid0's later reads */ \
    }                                                                  \
