// Minimal G-way per-group sense-reversal barrier test.
extern "C" __global__ void bartest(int* bcnt, int* bsen, float* scr, int B, int G, int NITER, int SCRW){
    int g=blockIdx.x, bid=blockIdx.y; if(bid>=B) return;
    int tid=threadIdx.x;
    int* bc=bcnt+bid; int* bs=bsen+bid; float* s=scr+(long)bid*SCRW;
    int priv=0;
    #define BAR() do{ __syncthreads(); if(tid==0){ int my=priv^1; priv=my; \
        if(atomicAdd(bc,1)==G-1){ atomicExch(bc,0); \
            asm volatile("st.release.gpu.b32 [%0], %1;"::"l"(bs),"r"(my):"memory"); } \
        else { int sn; do{ asm volatile("ld.acquire.gpu.b32 %0,[%1];":"=r"(sn):"l"(bs):"memory"); }while(sn!=my);} } \
        __syncthreads(); }while(0)
    for(int it=0; it<NITER; ++it){
        // each iter: zero by g0, barrier, each CTA adds (g+1), barrier, check sum==G*(G+1)/2
        if(g==0 && tid==0) ((volatile float*)s)[0]=0.0f;
        BAR();
        if(tid==0) atomicAdd(&s[0], (float)(g+1));
        BAR();
        if(tid==0){ float tot=((volatile float*)s)[0]; float want=(float)(G*(G+1)/2);
            if(tot!=want) atomicAdd(&s[1], 1.0f); }  // count mismatches
        BAR();
    }
    #undef BAR
}
